-- Check the imported table against the build that produced its CSV.
-- Generated by python -m epc_nd_ingest.sql_check from the output schema and the export contract.
--
-- It reads the table; it never repairs, replaces or promotes anything. The expected values
-- come from results/manifest.json, which is the build's own record, never from the loaded table.
--
-- What this establishes: the declared columns, types, widths, nullability and order are
-- present, the natural key is unique and not null, no text contains the framing characters,
-- the row count matches, and the recomputed digest matches.
-- What it does not: the digest truncates each SHA-256 to eight bytes and adds the results, so
-- collisions and cancelling changes are possible. It detects accidental load corruption.

SET NOCOUNT ON;
SET XACT_ABORT ON;

-- STEP 1. EDIT. Paste this build's numbers from results/manifest.json (csv.rows, csv.digest.total).
IF OBJECT_ID(N'tempdb..#expected', N'U') IS NOT NULL DROP TABLE #expected;
CREATE TABLE #expected (name sysname PRIMARY KEY, row_count bigint NOT NULL,
                        digest_total decimal(38,0) NOT NULL, digest_version int NOT NULL);
INSERT INTO #expected (name, row_count, digest_total, digest_version) VALUES
    (N'epc_nondomestic', 0, 0, 1)   -- EDIT: rows and total from manifest csv.digest
;

IF EXISTS (SELECT 1 FROM #expected WHERE digest_version <> 1)
    THROW 51000, 'This script implements digest definition version 1 only.', 1;
IF EXISTS (SELECT 1 FROM #expected WHERE row_count <= 0)
    THROW 51000, 'Expected row count and digest total have not been filled in from the manifest.', 1;

IF OBJECT_ID(N'tempdb..#result', N'U') IS NOT NULL DROP TABLE #result;
CREATE TABLE #result (table_name sysname, check_name nvarchar(200), expected nvarchar(200),
                      actual nvarchar(200), difference bigint NULL, passed bit NOT NULL);

-- ============================================================================================
-- epc_nondomestic: structure, key, then the digest
-- ============================================================================================
IF OBJECT_ID(N'epc_nondomestic', N'U') IS NULL
    INSERT INTO #result VALUES (N'epc_nondomestic', N'table exists', N'a table', N'not found', NULL, 0);
ELSE
BEGIN
    -- 1. Structure. A digest cannot establish any of this. max_length is in bytes, so an
    -- nvarchar(n) declares 2n and nvarchar(max) declares -1; NULL means not compared.
    DECLARE @declared TABLE (name sysname, ordinal int, type_name sysname,
                             numeric_precision int, numeric_scale int, max_length int, is_nullable bit);
    INSERT INTO @declared (name, ordinal, type_name, numeric_precision, numeric_scale, max_length, is_nullable) VALUES
    (N'epc_release', 1, N'nvarchar', NULL, NULL, 16, 0),
    (N'source_row', 2, N'int', NULL, NULL, NULL, 0),
    (N'HISTORIC', 3, N'nvarchar', NULL, NULL, 16, 0),
    (N'BUILDING_REFERENCE_NUMBER', 4, N'nvarchar', NULL, NULL, 64, 0),
    (N'OSG_REFERENCE_NUMBER', 5, N'nvarchar', NULL, NULL, 64, 0),
    (N'ADDRESS1', 6, N'nvarchar', NULL, NULL, 200, 0),
    (N'ADDRESS2', 7, N'nvarchar', NULL, NULL, 200, 0),
    (N'POST_TOWN', 8, N'nvarchar', NULL, NULL, 200, 0),
    (N'POSTCODE', 9, N'nvarchar', NULL, NULL, 64, 0),
    (N'INSPECTION_DATE', 10, N'nvarchar', NULL, NULL, 64, 0),
    (N'LODGEMENT_DATE', 11, N'nvarchar', NULL, NULL, 64, 0),
    (N'PROPERTY_TYPE_SHORT', 12, N'nvarchar', NULL, NULL, 64, 0),
    (N'PROPERTY_TYPE', 13, N'nvarchar', NULL, NULL, 200, 0),
    (N'FLOOR_AREA', 14, N'nvarchar', NULL, NULL, 16, 0),
    (N'CURRENT_ENERGY_PERFORMANCE_RATING', 15, N'nvarchar', NULL, NULL, 16, 0),
    (N'CURRENT_ENERGY_PERFORMANCE_BAND', 16, N'nvarchar', NULL, NULL, 64, 0),
    (N'POTENTIAL_ENERGY_PERFORMANCE_RATING', 17, N'nvarchar', NULL, NULL, 64, 0),
    (N'POTENTIAL_ENERGY_PERFORMANCE_BAND', 18, N'nvarchar', NULL, NULL, 64, 0),
    (N'NEW_BUILD_ENERGY_PERFORMANCE_RATING', 19, N'nvarchar', NULL, NULL, 16, 0),
    (N'NEW_BUILD_ENERGY_PERFORMANCE_BAND', 20, N'nvarchar', NULL, NULL, 16, 0),
    (N'MEETS_2002_STANDARD', 21, N'nvarchar', NULL, NULL, 16, 0),
    (N'ASSET_RATING', 22, N'nvarchar', NULL, NULL, 64, 0),
    (N'ASSET_RATING_BAND', 23, N'nvarchar', NULL, NULL, 64, 0),
    (N'BUILDING_EMISSIONS', 24, N'nvarchar', NULL, NULL, 64, 0),
    (N'RENEWABLE_SOURCES', 25, N'nvarchar', NULL, NULL, 64, 0),
    (N'ELECTRICITY_SOURCE', 26, N'nvarchar', NULL, NULL, 64, 0),
    (N'MAIN_HEATING_FUEL', 27, N'nvarchar', NULL, NULL, 200, 0),
    (N'BUILDING_ENVIRONMENT', 28, N'nvarchar', NULL, NULL, 200, 0),
    (N'PRIMARY_ENERGY_VALUE', 29, N'nvarchar', NULL, NULL, 16, 0),
    (N'APPROXIMATE_ENERGY_USE', 30, N'nvarchar', NULL, NULL, 16, 0),
    (N'IMPROVEMENT_RECOMMENDATIONS', 31, N'nvarchar', NULL, NULL, -1, 0),
    (N'LOCAL_AUTHORITY', 32, N'nvarchar', NULL, NULL, 16, 0),
    (N'DATA_ZONE', 33, N'nvarchar', NULL, NULL, 200, 0),
    (N'CONSTITUENCY', 34, N'nvarchar', NULL, NULL, 16, 0),
    (N'CONSTITUENCY_LABEL', 35, N'nvarchar', NULL, NULL, 200, 0),
    (N'TRANSACTION_TYPE', 36, N'nvarchar', NULL, NULL, 200, 0),
    (N'TARGET_EMISSIONS', 37, N'nvarchar', NULL, NULL, 16, 0),
    (N'DATA_ZONE_2011', 38, N'nvarchar', NULL, NULL, 200, 0),
    (N'CREATED_AT', 39, N'nvarchar', NULL, NULL, 64, 0),
    (N'REPORT_REFERENCE_NUMBER', 40, N'nvarchar', NULL, NULL, 64, 0),
    (N'rrn', 41, N'nvarchar', NULL, NULL, 48, 1),
    (N'uprn_sepcr', 42, N'bigint', NULL, NULL, NULL, 0),
    (N'uprn_osg', 43, N'bigint', NULL, NULL, NULL, 1),
    (N'pc_norm', 44, N'nvarchar', NULL, NULL, 64, 1),
    (N'datazone_2001', 45, N'nvarchar', NULL, NULL, 18, 1),
    (N'datazone_2001_status', 46, N'nvarchar', NULL, NULL, 32, 0),
    (N'datazone_2011', 47, N'nvarchar', NULL, NULL, 18, 1),
    (N'datazone_2011_status', 48, N'nvarchar', NULL, NULL, 32, 0),
    (N'inspection_date_parsed', 49, N'date', NULL, NULL, NULL, 0),
    (N'lodgement_date_parsed', 50, N'date', NULL, NULL, NULL, 0),
    (N'created_at_parsed', 51, N'datetime2', 19, 0, NULL, 0),
    (N'historic_flag', 52, N'bit', NULL, NULL, NULL, 0),
    (N'floor_area_int', 53, N'int', NULL, NULL, NULL, 0),
    (N'current_energy_performance_rating_int', 54, N'int', NULL, NULL, NULL, 0),
    (N'potential_energy_performance_rating_num', 55, N'decimal', 19, 4, NULL, 1),
    (N'building_emissions_num', 56, N'decimal', 19, 4, NULL, 0),
    (N'primary_energy_value_int', 57, N'int', NULL, NULL, NULL, 0);

    INSERT INTO #result
    SELECT N'epc_nondomestic', N'columns declared and in order', N'0 differences',
           CONVERT(nvarchar(200), COUNT(*)) + N' differences', COUNT(*), CASE WHEN COUNT(*) = 0 THEN 1 ELSE 0 END
    FROM (
        -- Bound to the one object being checked by OBJECT_ID, never by name alone.
        SELECT d.name FROM @declared d
        LEFT JOIN (SELECT c.name, c.column_id, t.name AS type_name, c.precision, c.scale, c.max_length, c.is_nullable
                   FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id
                   WHERE c.object_id = OBJECT_ID(N'epc_nondomestic', N'U')) c
               ON c.name = d.name AND c.column_id = d.ordinal AND c.type_name = d.type_name
              AND (d.numeric_precision IS NULL
                   OR (c.precision = d.numeric_precision AND c.scale = d.numeric_scale))
              AND (d.max_length IS NULL OR c.max_length = d.max_length)
              AND c.is_nullable = d.is_nullable
        WHERE c.name IS NULL
        UNION ALL
        SELECT c.name FROM sys.columns c
        WHERE c.object_id = OBJECT_ID(N'epc_nondomestic', N'U')
          AND c.name NOT IN (SELECT name FROM @declared)
    ) AS differences;

    -- 2. The natural key: the digest is order independent, so a duplicated row and a missing
    -- one can cancel out.
    INSERT INTO #result
    SELECT N'epc_nondomestic', N'natural key [epc_release], [source_row] unique and not null', N'0 offending rows',
           CONVERT(nvarchar(200), COUNT_BIG(*)) + N' offending rows', COUNT_BIG(*),
           CASE WHEN COUNT_BIG(*) = 0 THEN 1 ELSE 0 END
    FROM (SELECT [epc_release], [source_row] FROM epc_nondomestic GROUP BY [epc_release], [source_row] HAVING COUNT_BIG(*) > 1) AS duplicates;

    -- 3. Reserved framing characters in the text columns.
    INSERT INTO #result
    SELECT N'epc_nondomestic', N'no reserved framing characters in text', N'0 rows',
           CONVERT(nvarchar(200), COUNT_BIG(*)) + N' rows', COUNT_BIG(*),
           CASE WHEN COUNT_BIG(*) = 0 THEN 1 ELSE 0 END
    FROM epc_nondomestic
    WHERE DATALENGTH(REPLACE(REPLACE([epc_release] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([epc_release])
       OR DATALENGTH(REPLACE(REPLACE([HISTORIC] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([HISTORIC])
       OR DATALENGTH(REPLACE(REPLACE([BUILDING_REFERENCE_NUMBER] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([BUILDING_REFERENCE_NUMBER])
       OR DATALENGTH(REPLACE(REPLACE([OSG_REFERENCE_NUMBER] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([OSG_REFERENCE_NUMBER])
       OR DATALENGTH(REPLACE(REPLACE([ADDRESS1] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([ADDRESS1])
       OR DATALENGTH(REPLACE(REPLACE([ADDRESS2] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([ADDRESS2])
       OR DATALENGTH(REPLACE(REPLACE([POST_TOWN] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([POST_TOWN])
       OR DATALENGTH(REPLACE(REPLACE([POSTCODE] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([POSTCODE])
       OR DATALENGTH(REPLACE(REPLACE([INSPECTION_DATE] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([INSPECTION_DATE])
       OR DATALENGTH(REPLACE(REPLACE([LODGEMENT_DATE] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([LODGEMENT_DATE])
       OR DATALENGTH(REPLACE(REPLACE([PROPERTY_TYPE_SHORT] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([PROPERTY_TYPE_SHORT])
       OR DATALENGTH(REPLACE(REPLACE([PROPERTY_TYPE] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([PROPERTY_TYPE])
       OR DATALENGTH(REPLACE(REPLACE([FLOOR_AREA] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([FLOOR_AREA])
       OR DATALENGTH(REPLACE(REPLACE([CURRENT_ENERGY_PERFORMANCE_RATING] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([CURRENT_ENERGY_PERFORMANCE_RATING])
       OR DATALENGTH(REPLACE(REPLACE([CURRENT_ENERGY_PERFORMANCE_BAND] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([CURRENT_ENERGY_PERFORMANCE_BAND])
       OR DATALENGTH(REPLACE(REPLACE([POTENTIAL_ENERGY_PERFORMANCE_RATING] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([POTENTIAL_ENERGY_PERFORMANCE_RATING])
       OR DATALENGTH(REPLACE(REPLACE([POTENTIAL_ENERGY_PERFORMANCE_BAND] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([POTENTIAL_ENERGY_PERFORMANCE_BAND])
       OR DATALENGTH(REPLACE(REPLACE([NEW_BUILD_ENERGY_PERFORMANCE_RATING] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([NEW_BUILD_ENERGY_PERFORMANCE_RATING])
       OR DATALENGTH(REPLACE(REPLACE([NEW_BUILD_ENERGY_PERFORMANCE_BAND] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([NEW_BUILD_ENERGY_PERFORMANCE_BAND])
       OR DATALENGTH(REPLACE(REPLACE([MEETS_2002_STANDARD] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([MEETS_2002_STANDARD])
       OR DATALENGTH(REPLACE(REPLACE([ASSET_RATING] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([ASSET_RATING])
       OR DATALENGTH(REPLACE(REPLACE([ASSET_RATING_BAND] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([ASSET_RATING_BAND])
       OR DATALENGTH(REPLACE(REPLACE([BUILDING_EMISSIONS] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([BUILDING_EMISSIONS])
       OR DATALENGTH(REPLACE(REPLACE([RENEWABLE_SOURCES] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([RENEWABLE_SOURCES])
       OR DATALENGTH(REPLACE(REPLACE([ELECTRICITY_SOURCE] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([ELECTRICITY_SOURCE])
       OR DATALENGTH(REPLACE(REPLACE([MAIN_HEATING_FUEL] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([MAIN_HEATING_FUEL])
       OR DATALENGTH(REPLACE(REPLACE([BUILDING_ENVIRONMENT] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([BUILDING_ENVIRONMENT])
       OR DATALENGTH(REPLACE(REPLACE([PRIMARY_ENERGY_VALUE] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([PRIMARY_ENERGY_VALUE])
       OR DATALENGTH(REPLACE(REPLACE([APPROXIMATE_ENERGY_USE] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([APPROXIMATE_ENERGY_USE])
       OR DATALENGTH(REPLACE(REPLACE([IMPROVEMENT_RECOMMENDATIONS] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([IMPROVEMENT_RECOMMENDATIONS])
       OR DATALENGTH(REPLACE(REPLACE([LOCAL_AUTHORITY] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([LOCAL_AUTHORITY])
       OR DATALENGTH(REPLACE(REPLACE([DATA_ZONE] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([DATA_ZONE])
       OR DATALENGTH(REPLACE(REPLACE([CONSTITUENCY] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([CONSTITUENCY])
       OR DATALENGTH(REPLACE(REPLACE([CONSTITUENCY_LABEL] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([CONSTITUENCY_LABEL])
       OR DATALENGTH(REPLACE(REPLACE([TRANSACTION_TYPE] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([TRANSACTION_TYPE])
       OR DATALENGTH(REPLACE(REPLACE([TARGET_EMISSIONS] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([TARGET_EMISSIONS])
       OR DATALENGTH(REPLACE(REPLACE([DATA_ZONE_2011] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([DATA_ZONE_2011])
       OR DATALENGTH(REPLACE(REPLACE([CREATED_AT] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([CREATED_AT])
       OR DATALENGTH(REPLACE(REPLACE([REPORT_REFERENCE_NUMBER] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([REPORT_REFERENCE_NUMBER])
       OR DATALENGTH(REPLACE(REPLACE([rrn] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([rrn])
       OR DATALENGTH(REPLACE(REPLACE([pc_norm] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([pc_norm])
       OR DATALENGTH(REPLACE(REPLACE([datazone_2001] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([datazone_2001])
       OR DATALENGTH(REPLACE(REPLACE([datazone_2001_status] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([datazone_2001_status])
       OR DATALENGTH(REPLACE(REPLACE([datazone_2011] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([datazone_2011])
       OR DATALENGTH(REPLACE(REPLACE([datazone_2011_status] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([datazone_2011_status]);

    -- 4. The row count and the digest, rendered as the CSV renders each row, NCHAR(0) for a
    -- null, fields joined with NCHAR(31) in contract order, hashed as UTF-8, the signed
    -- eight-byte prefixes summed as decimal. The first operand of each chunk is nvarchar(max)
    -- so CONCAT_WS cannot truncate a long row.
    INSERT INTO #result
    SELECT N'epc_nondomestic', N'row count', CONVERT(nvarchar(200), e.row_count),
           CONVERT(nvarchar(200), q.n), ABS(q.n - e.row_count),
           CASE WHEN q.n = e.row_count THEN 1 ELSE 0 END
    FROM #expected e CROSS JOIN (SELECT COUNT_BIG(*) AS n FROM epc_nondomestic) AS q
    WHERE e.name = N'epc_nondomestic';

    INSERT INTO #result
    SELECT N'epc_nondomestic', N'row digest, definition version ' + CONVERT(nvarchar(10), e.digest_version),
           CONVERT(nvarchar(200), e.digest_total), CONVERT(nvarchar(200), ISNULL(q.total, 0)),
           CASE WHEN ISNULL(q.total, 0) = e.digest_total THEN 0 ELSE 1 END,
           CASE WHEN ISNULL(q.total, 0) = e.digest_total THEN 1 ELSE 0 END
    FROM #expected e CROSS JOIN (
        SELECT SUM(CONVERT(decimal(38,0), CONVERT(bigint, SUBSTRING(HASHBYTES('SHA2_256',
                   CONVERT(varchar(max), CONCAT_WS(NCHAR(31),
           CONVERT(nvarchar(max), ISNULL([epc_release], NCHAR(0))),
           ISNULL(CONVERT(varchar(20), [source_row]), NCHAR(0)),
           ISNULL([HISTORIC], NCHAR(0)),
           ISNULL([BUILDING_REFERENCE_NUMBER], NCHAR(0)),
           ISNULL([OSG_REFERENCE_NUMBER], NCHAR(0)),
           ISNULL([ADDRESS1], NCHAR(0)),
           ISNULL([ADDRESS2], NCHAR(0)),
           ISNULL([POST_TOWN], NCHAR(0)),
           ISNULL([POSTCODE], NCHAR(0)),
           ISNULL([INSPECTION_DATE], NCHAR(0)),
           ISNULL([LODGEMENT_DATE], NCHAR(0)),
           ISNULL([PROPERTY_TYPE_SHORT], NCHAR(0)),
           ISNULL([PROPERTY_TYPE], NCHAR(0)),
           ISNULL([FLOOR_AREA], NCHAR(0)),
           ISNULL([CURRENT_ENERGY_PERFORMANCE_RATING], NCHAR(0)),
           ISNULL([CURRENT_ENERGY_PERFORMANCE_BAND], NCHAR(0)),
           ISNULL([POTENTIAL_ENERGY_PERFORMANCE_RATING], NCHAR(0)),
           ISNULL([POTENTIAL_ENERGY_PERFORMANCE_BAND], NCHAR(0)),
           ISNULL([NEW_BUILD_ENERGY_PERFORMANCE_RATING], NCHAR(0)),
           ISNULL([NEW_BUILD_ENERGY_PERFORMANCE_BAND], NCHAR(0)),
           ISNULL([MEETS_2002_STANDARD], NCHAR(0)),
           ISNULL([ASSET_RATING], NCHAR(0)),
           ISNULL([ASSET_RATING_BAND], NCHAR(0)),
           ISNULL([BUILDING_EMISSIONS], NCHAR(0)),
           ISNULL([RENEWABLE_SOURCES], NCHAR(0)),
           ISNULL([ELECTRICITY_SOURCE], NCHAR(0)),
           ISNULL([MAIN_HEATING_FUEL], NCHAR(0)),
           ISNULL([BUILDING_ENVIRONMENT], NCHAR(0)),
           ISNULL([PRIMARY_ENERGY_VALUE], NCHAR(0)),
           ISNULL([APPROXIMATE_ENERGY_USE], NCHAR(0)),
           ISNULL([IMPROVEMENT_RECOMMENDATIONS], NCHAR(0)),
           ISNULL([LOCAL_AUTHORITY], NCHAR(0)),
           ISNULL([DATA_ZONE], NCHAR(0)),
           ISNULL([CONSTITUENCY], NCHAR(0)),
           ISNULL([CONSTITUENCY_LABEL], NCHAR(0)),
           ISNULL([TRANSACTION_TYPE], NCHAR(0)),
           ISNULL([TARGET_EMISSIONS], NCHAR(0)),
           ISNULL([DATA_ZONE_2011], NCHAR(0)),
           ISNULL([CREATED_AT], NCHAR(0)),
           ISNULL([REPORT_REFERENCE_NUMBER], NCHAR(0)),
           ISNULL([rrn], NCHAR(0)),
           ISNULL(CONVERT(varchar(20), [uprn_sepcr]), NCHAR(0)),
           ISNULL(CONVERT(varchar(20), [uprn_osg]), NCHAR(0)),
           ISNULL([pc_norm], NCHAR(0)),
           ISNULL([datazone_2001], NCHAR(0)),
           ISNULL([datazone_2001_status], NCHAR(0)),
           ISNULL([datazone_2011], NCHAR(0)),
           ISNULL([datazone_2011_status], NCHAR(0)),
           ISNULL(CONVERT(varchar(10), [inspection_date_parsed], 23), NCHAR(0)),
           ISNULL(CONVERT(varchar(10), [lodgement_date_parsed], 23), NCHAR(0)),
           ISNULL(CONVERT(varchar(19), [created_at_parsed], 120), NCHAR(0)),
           ISNULL(CONVERT(varchar(1), [historic_flag]), NCHAR(0)),
           ISNULL(CONVERT(varchar(20), [floor_area_int]), NCHAR(0)),
           ISNULL(CONVERT(varchar(20), [current_energy_performance_rating_int]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [potential_energy_performance_rating_num]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [building_emissions_num]), NCHAR(0)),
           ISNULL(CONVERT(varchar(20), [primary_energy_value_int]), NCHAR(0))) COLLATE Latin1_General_100_BIN2_UTF8)), 1, 8)))) AS total
        FROM epc_nondomestic) AS q
    WHERE e.name = N'epc_nondomestic';
END

-- ============================================================================================
-- The result. A skipped check is not a pass, so an absent row fails the count below.
-- ============================================================================================
SELECT table_name, check_name, expected, actual, difference,
       CASE passed WHEN 1 THEN 'pass' ELSE 'FAIL' END AS outcome
FROM #result ORDER BY table_name, check_name;

DECLARE @failed int = (SELECT COUNT(*) FROM #result WHERE passed = 0);
DECLARE @ran int = (SELECT COUNT(*) FROM #result);
IF @failed > 0 OR @ran <> 5
    THROW 51000, 'The imported table does not match the build: see the result above.', 1;
